/**
 * Several stacks from docker-compose.from-registry.yml can share one host.
 *
 * Every container, network and volume name in the registry stack carries the
 * stack name, and the plain install (no STACK_NAME) resolves to exactly the
 * names it always had: a volume that changes name on upgrade is a volume the
 * stack can no longer find. The shared sidecars (docker-compose.sidecars.yml)
 * publish no port and never put two stacks on one network: the per-stack
 * networks are generated by selfhost-sidecars.sh, and a stack's server joins
 * only its own one through the shared-sidecars override.
 *
 * Run: node --test scripts/compose-stack-name.test.mjs
 */

import test from 'node:test';
import assert from 'node:assert';
import fs from 'node:fs';
import path from 'node:path';
import { REPO } from './lib/docker-stub.mjs';

const read = (rel) => fs.readFileSync(path.join(REPO, rel), 'utf8');
const REGISTRY = 'docker-compose.from-registry.yml';
const SIDECARS = 'docker-compose.sidecars.yml';
const OVERRIDE = 'docker-compose.shared-sidecars.override.yml';

/** Interpolate `${NAME:-default}` / `${NAME}` the way compose does for a plain install. */
const plain = (s) => s.replace(/\$\{([A-Z_]+)(?::-([^}]*))?\}/g, (_, _k, d) => d ?? '');

test('every container_name of the registry stack carries the stack name', () => {
    const names = [...read(REGISTRY).matchAll(/^\s+container_name:\s*(\S+)/gm)].map((m) => m[1]);
    assert.ok(names.length >= 9, `expected the services to name their containers, found ${names.length}`);
    for (const n of names) {
        assert.match(n, /^\$\{STACK_NAME:-beeflow\}-[a-z-]+$/, `${n}: use \${STACK_NAME:-beeflow}-<service>`);
    }
});

test('network and volume names carry the stack name and keep their plain-install names', () => {
    const text = read(REGISTRY);
    const tail = text.slice(text.indexOf('\nvolumes:'));
    const names = [...tail.matchAll(/^\s+name:\s*(\S+)/gm)].map((m) => m[1]);
    assert.deepStrictEqual(names.map(plain).sort(), [
        'beeflow-browser-network', 'beeflow-data', 'beeflow-network', 'beeflow-pgdata', 'rustfs-data', 'rustfs-logs',
    ], 'a plain install must resolve to the names it had before STACK_NAME existed');
    for (const n of names) {
        assert.ok(/\$\{STACK_NAME:-beeflow\}|\$\{STACK_VOLUME_PREFIX:-\}/.test(n), `${n}: not parameterised by stack`);
    }
});

test('the components mount is per stack', () => {
    assert.match(read(REGISTRY), /^\s+- \$\{COMPONENTS_DIR:-\.\/components\}:\/components$/m);
});

test('agent-hub publishes through CLIENT_BIND_HOST, 0.0.0.0 for the plain install', () => {
    assert.match(read(REGISTRY), /^\s+- "\$\{CLIENT_BIND_HOST:-0\.0\.0\.0\}:\$\{CLIENT_PORT:-5176\}:80"$/m);
});

test('the shared sidecars publish no port and run no stateful service', () => {
    const text = read(SIDECARS);
    assert.ok(!/^\s+ports:/m.test(text), 'a published port is the one thing a host firewall cannot close');
    const block = text.slice(text.indexOf('\nservices:'), text.indexOf('\nvolumes:'));
    const services = [...block.matchAll(/^  ([a-z-]+):$/gm)].map((m) => m[1]);
    assert.deepStrictEqual(services, ['guard-service', 'guard-redis', 'classify-service', 'ollama']);
    for (const svc of ['guard-service', 'classify-service']) {
        assert.ok(new RegExp(`${svc}:[\\s\\S]*?SERVICES_API_KEY=\\$\\{SERVICES_API_KEY:\\?`).test(text), `${svc} must refuse to start without the key`);
    }
    assert.match(text, /GUARD_LOG_LEVEL=\$\{GUARD_LOG_LEVEL:-WARNING\}/, 'one guard sees every stack: request content stays out of its log');
    assert.match(text, /sidecars-internal:\n\s+name: [^\n]+\n\s+internal: true/);
});

test('the shared-sidecars override joins only the server to the stack\'s own external network', () => {
    const text = read(OVERRIDE);
    assert.deepStrictEqual([...text.matchAll(/^  ([a-z-]+):$/gm)].map((m) => m[1]), ['server', 'shared-sidecars']);
    assert.match(text, /name: \$\{STACK_NAME:-beeflow\}-sidecars\n\s+external: true/);
});

test('selfhost.sh runs a named stack as its own compose project with its own env file', () => {
    const sh = read('selfhost.sh');
    assert.match(sh, /ENV_FILE="\$SCRIPT_DIR\/\.env\.\$STACK_NAME"/);
    assert.match(sh, /PROJECT_ARGS=\(-p "\$STACK_NAME" --env-file "\$ENV_FILE"\)/);
    assert.match(sh, /export STACK_VOLUME_PREFIX="\$\{STACK_NAME\}-"/);
    assert.match(sh, /export COMPONENTS_DIR="\.\/components\.\$STACK_NAME"/);
    assert.match(sh, /docker compose "\$\{PROJECT_ARGS\[@\]\}" "\$@"/, 'every compose call carries the project');
    assert.match(sh, /\[ -n "\$SHARED_SIDECARS" \] && COMPOSE_FILES\+=\(-f "\$SHARED_OVERRIDE"\)/);
    assert.ok(!/docker exec beeflow-server/.test(sh), 'docker exec must address the stack\'s server container');
    assert.match(sh, /set_env SHARED_SIDECARS/, 'the choice is saved like PROFILES and DOCKER_SOCKET');
});

test('the generated networks file and per-stack env files are ignored by git', () => {
    const ignore = read('.gitignore');
    for (const line of ['.env.*', '!.env.example', '!.env.*.example', 'components.*/', 'docker-compose.sidecars.networks.yml']) {
        assert.ok(ignore.split('\n').includes(line), `.gitignore lacks ${line}`);
    }
});
